    rows, cols = len(grid), len(grid[0])

    special = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] not in (0, 8):
                special[(r,c)] = grid[r][c]

    vals = collections.Counter(special.values())
    center_val = min(vals, key=vals.get)
    arm_val = max(vals, key=vals.get)
    center = [pos for pos, v in special.items() if v == center_val][0]

    dist = {center: 0}
